// Sets D2SLogStrc.bTimestamps, which makes SLOG_OutputTime prefix each entry with the local time.
// Provenance: 1.14d asm 00420160 (SLOG_LockLog, [ctx+0x18] = flag); name from the Mac PPC Storm import list (SLogSetTimestamp).
void __stdcall SLogSetTimestamp(uint32_t nHandle, uint32_t bTimestamps) {
    D2SLogStrc* pContext = SLOG_LockLog(&nHandle, 0, nHandle);
    if (!pContext) {
      return;
    }

    pContext->bTimestamps = bTimestamps;
    SLOG_UnlockLog(nHandle);
}

// @blizzard SLogWrite (SLOG.CPP)
void SLogWrite(uint32_t nHandle, char * szFormat, ...) {
    va_list __va;
    va_start(__va, szFormat);
    uint32_t nSlot;
    D2SLogStrc* pContext = SLOG_LockLog(&nSlot, 0, nHandle);
    if (!pContext) {
      return;
    }

    SLOG_OutputTime(1, pContext);
    vsprintf(pContext->acBuffer + pContext->nUsed, szFormat, __va);
    uint32_t nWritten = SSTR::SStrLen(pContext->acBuffer + pContext->nUsed);
    pContext->nUsed += nWritten;
    SLOG_OutputReturn(pContext);
    if (gbCompressionDebugOutput) {
      /* LPCSTR lpOutputString for OutputDebugStringA */ OutputDebugStringA(pContext->acBuffer + pContext->nLineStart);
    }

    pContext->nLineStart = pContext->nUsed;
    if (pContext->nUsed >= 0xc000) {
      SLOG_FlushLog(pContext);
    }

    SLOG_UnlockLog(nSlot);
}

// @blizzard SLogDestroy (SLOG.CPP)
void __stdcall SLogDestroy() {
    int nSlotsLeft;
    SLogFlushAll();
    CRITICAL_SECTION* pCs = gaSLogCritSect;
    D2SLogStrc** ppListHead = gaSLogHead;
    int nRemaining = 4;
    do {
      D2SLogStrc* pNode;
      /* LPCRITICAL_SECTION lpCriticalSection for EnterCriticalSection */ nSlotsLeft = nRemaining;
      EnterCriticalSection(pCs);
      pNode = *ppListHead;
      while (pNode) {
        SLogClose(pNode->nHandle);
        SErr::SErrReportResourceLeak("HSLOG");
        pNode = *ppListHead;
      }

      /* LPCRITICAL_SECTION lpCriticalSection for LeaveCriticalSection */ LeaveCriticalSection(pCs);
      ppListHead++;
      pCs++;
      nRemaining = nSlotsLeft - 1;
    } while (nRemaining);

    nSlotsLeft += 3;
    pCs = gaSLogCritSect;
    do {
      /* LPCRITICAL_SECTION lpCriticalSection for DeleteCriticalSection */ DeleteCriticalSection(pCs);
      pCs++;
      nSlotsLeft--;
    } while (nSlotsLeft);
}

