uint32_t PKWARE_ExplodeStream(TDcmpStruct * pItemData) {
    // Frame slots -8..0 are ONE object: &nInventoryResult is passed out and the callee reaches the rest by byte offset.
    // Separate locals let the compiler reorder them, so the run is one struct.
    struct __frame0_t {
      uint32_t nInventoryResult;
      uint32_t nSeedOffset;
    };
    static_assert(sizeof(void*) != 4 || sizeof(__frame0_t) == 8, "frame group __frame0_t must reproduce the Ghidra frame layout");
    __frame0_t __frame0;
    int nCopyDistance;
    uint8_t* pWindowSrc;
    uint8_t* pWindowDst;
    uint8_t bWindowByte;
    pItemData->outputPos = 0x1000;
    do {
      __frame0.nInventoryResult = PKWARE_ProcessItemInventory(pItemData);
      if (0x304 < __frame0.nInventoryResult) {
        __frame0.nSeedOffset = pItemData->outputPos - 0x1000;
        pItemData->write_buf(pItemData->out_buff + 0x1000, &__frame0.nSeedOffset, pItemData->param);
        return __frame0.nInventoryResult;
      }
      if (__frame0.nInventoryResult < 0x100) {
        pItemData->out_buff[pItemData->outputPos] = (uint8_t)__frame0.nInventoryResult;
        pItemData->outputPos++;
      } else {
        __frame0.nInventoryResult -= 0xfe;
        nCopyDistance = PKWARE_GetItemDataValue(pItemData, __frame0.nInventoryResult);
        if (!nCopyDistance) {
          __frame0.nInventoryResult = 0x306;
          __frame0.nSeedOffset = pItemData->outputPos - 0x1000;
          pItemData->write_buf(pItemData->out_buff + 0x1000, &__frame0.nSeedOffset, pItemData->param);
          return __frame0.nInventoryResult;
        }

        pWindowDst = pItemData->out_buff + pItemData->outputPos;
        pWindowSrc = pWindowDst - nCopyDistance;
        pItemData->outputPos = __frame0.nInventoryResult + pItemData->outputPos;
        do {
          bWindowByte = *pWindowSrc;
          pWindowSrc++;
          *pWindowDst = bWindowByte;
          pWindowDst++;
          __frame0.nInventoryResult--;
        } while (__frame0.nInventoryResult);
      }
      if (pItemData->outputPos >= 0x2000) {
        __frame0.nInventoryResult = 0x1000;
        pItemData->write_buf(pItemData->out_buff + 0x1000, &__frame0.nInventoryResult, pItemData->param);
        PKWARE_SetMemoryValue((uint32_t*)pItemData->out_buff, (uint32_t*)(pItemData->out_buff + 0x1000), pItemData->outputPos - 0x1000);
        pItemData->outputPos -= 0x1000;
      }
    } while (true);
}

uint32_t PKWARE_ProcessItemInventory(TDcmpStruct * nParam) {
    BOOL nRangeCheckResult;
    uint32_t nDecodedValue;
    uint8_t nExtraBitCount;
    if (nParam->bit_buff & 1) {
      uint32_t nExtraBitsValue;
      nRangeCheckResult = PKWARE_CheckItemDataRange(nParam, 1);
      if (nRangeCheckResult) {
        return 0x306;
      }

      nDecodedValue = (uint32_t)nParam->LengthCodes[nParam->bit_buff & 0xff];
      nRangeCheckResult = PKWARE_CheckItemDataRange(nParam, (uint32_t)nParam->LenBits[nDecodedValue]);
      if (nRangeCheckResult) {
        return 0x306;
      }

      nExtraBitCount = nParam->ExLenBits[nDecodedValue];
      if (nExtraBitCount) {
        nExtraBitsValue = (1 << (nExtraBitCount & 0x1f)) - 1U & nParam->bit_buff;
        nRangeCheckResult = PKWARE_CheckItemDataRange(nParam, (uint32_t)nExtraBitCount);
        if (nRangeCheckResult && nDecodedValue + nExtraBitsValue != 0x10e) {
          return 0x306;
        }

        nDecodedValue = nParam->LenBase[nDecodedValue] + nExtraBitsValue;
      }

      nDecodedValue += 0x100;
    } else {
      nRangeCheckResult = PKWARE_CheckItemDataRange(nParam, 1);
      if (nRangeCheckResult) {
        return 0x306;
      }
      if (!nParam->ctype) {
        nDecodedValue = nParam->bit_buff & 0xff;
        nRangeCheckResult = PKWARE_CheckItemDataRange(nParam, 8);
        if (nRangeCheckResult) {
          return 0x306;
        }
      } else {
        nDecodedValue = nParam->bit_buff & 0xff;
        if (nDecodedValue) {
          nDecodedValue = (uint32_t)nParam->offs2C34[nDecodedValue];
          if (nDecodedValue == 0xff) {
            if (nParam->bit_buff & 0x3f) {
              nRangeCheckResult = PKWARE_CheckItemDataRange(nParam, 4);
              if (nRangeCheckResult) {
                return 0x306;
              }

              nDecodedValue = (uint32_t)nParam->offs2D34[nParam->bit_buff & 0xff];
            } else {
              nRangeCheckResult = PKWARE_CheckItemDataRange(nParam, 6);
              if (nRangeCheckResult) {
                return 0x306;
              }

              nDecodedValue = (uint32_t)nParam->offs2E34[nParam->bit_buff & 0x7f];
            }
          }
        } else {
          nRangeCheckResult = PKWARE_CheckItemDataRange(nParam, 8);
          if (nRangeCheckResult) {
            return 0x306;
          }

          nDecodedValue = (uint32_t)nParam->offs2EB4[nParam->bit_buff & 0xff];
        }

        nRangeCheckResult = PKWARE_CheckItemDataRange(nParam, (uint32_t)nParam->ChBitsAsc[nDecodedValue]);
        if (nRangeCheckResult) {
          return 0x306;
        }
      }
    }

    return nDecodedValue;
}

int PKWARE_GetItemDataValue(TDcmpStruct * pClientSideData, int nParam) {
    uint32_t uDataValue = (uint32_t)pClientSideData->DistPosCodes[pClientSideData->bit_buff & 0xff];
    BOOL nRangeCheckResult = PKWARE_CheckItemDataRange(pClientSideData, (uint32_t)pClientSideData->DistBits[uDataValue]);
    if (nRangeCheckResult) {
      return 0;
    }
    if (nParam == 2) {
      uDataValue = uDataValue << 2 | pClientSideData->bit_buff & 3;
      nRangeCheckResult = PKWARE_CheckItemDataRange(pClientSideData, 2);
      if (nRangeCheckResult) {
        return 0;
      }
    } else {
      uDataValue = uDataValue << ((uint8_t)pClientSideData->dsize_bits & 0x1f) | pClientSideData->dsize_mask & pClientSideData->bit_buff;
      nRangeCheckResult = PKWARE_CheckItemDataRange(pClientSideData, pClientSideData->dsize_bits);
      if (nRangeCheckResult) {
        return 0;
      }
    }

    return uDataValue + 1;
}

BOOL PKWARE_CheckItemDataRange(TDcmpStruct * pClientSideData, uint32_t nParam) {
    uint8_t bNextByte;
    uint32_t dwBitBuffer = pClientSideData->extra_bits;
    if (dwBitBuffer >= nParam) {
      pClientSideData->extra_bits = dwBitBuffer - nParam;
      pClientSideData->bit_buff >>= (uint8_t)nParam & 0x1f;
      return 0;
    }

    uint32_t* pInPos = &pClientSideData->in_pos;
    pClientSideData->bit_buff >>= (uint8_t)dwBitBuffer & 0x1f;
    if (*pInPos == pClientSideData->in_bytes) {
      *pInPos = 0x800;
      dwBitBuffer = pClientSideData->read_buf(pClientSideData->in_buff, pInPos, pClientSideData->param);
      pClientSideData->in_bytes = dwBitBuffer;
      if (!dwBitBuffer) {
        return 1;
      }

      *pInPos = 0;
    }

    bNextByte = pClientSideData->in_buff[*pInPos];
    (*pInPos)++;
    dwBitBuffer = (uint32_t)bNextByte << 8 | pClientSideData->bit_buff;
    pClientSideData->bit_buff = dwBitBuffer;
    pClientSideData->bit_buff = dwBitBuffer >> ((uint8_t)nParam - (char)pClientSideData->extra_bits & 0x1f);
    pClientSideData->extra_bits = pClientSideData->extra_bits - nParam + 8;
    return 0;
}

void PKWARE_CompareItemValues(int nCount, uint8_t * pBitsTable, uint8_t * pBaseTable, char * pOutTable) {
    uint8_t nBitLen;
    while (true) {
      uint32_t nBaseIndex;
      nCount--;
      if (nCount < 0) {
        break;
      }

      nBitLen = pBitsTable[nCount];
      nBaseIndex = (uint32_t)pBaseTable[nCount];
      do {
        pOutTable[nBaseIndex] = (char)nCount;
        nBaseIndex += 1 << (nBitLen & 0x1f);
      } while (nBaseIndex < 0x100);
    }
}

